// Тикеты #6a86f7ff · 2a12bdf47ce0 «פיתוח: הסבר והכוונה על התפילה הנוכחית»; #6a86f7e16f63 (мокап חלון הסבר); #a5decf4a (утверждение через админку).
// Опора: F-42 AC1–AC4 · S-21 «חלון הסבר על התפילה» (Figma 454:4469). Закрытие — только ✕ (без «סגירה והמשך בתפילה»).
import { expect } from '@wdio/globals';
import { byText, byTextContains, byTextMatches, byLabel, tapLabel, expectVisibleText, pageCounter } from '../../helpers/ui.ts';
import { openPrayer } from '../../helpers/nav.ts';
import { toHome } from '../../helpers/app.ts';

const TEMP_LINE = 'נוסח זמני, עד לאישור הנוסח הסופי.';
const APPROVED_LINE = 'מקור: .+אושר על ידי .+\\d{1,2}\\.\\d{1,2}\\.\\d{4}.*';

/** Открыть молитву и окно ⓘ «על התפילה»: заголовок «על תפילת <имя>», «💡 טיפ: …», нет «סגירה והמשך בתפילה». */
async function openInfo(key: string, prayerName: string) {
  await openPrayer(key, prayerName);
  await expectVisibleText(`${prayerName} (אשכנזי)`);
  const before = await pageCounter();
  await tapLabel('הסבר על התפילה');
  await expectVisibleText(`על תפילת ${prayerName}`);
  await expect(byTextMatches('.*טיפ: \\S.*')).toBeDisplayed();
  await expect(byText('סגירה והמשך בתפילה')).not.toBeDisplayed();
  await expect(byLabel('סגירה והמשך בתפילה')).not.toBeDisplayed();
  return before;
}

/** ✕ — единственное закрытие: окно закрыто, та же молитва и тот же קטע. */
async function closeAndCheck(prayerName: string, before: string) {
  await tapLabel('סגירה');
  await expect(byText(`על תפילת ${prayerName}`)).not.toBeDisplayed();
  await expectVisibleText(`${prayerName} (אשכנזי)`);
  expect(await pageCounter()).toBe(before);
}

describe('Молитва по шагам', () => {
  afterEach(async () => { await toHome(); });

  it('GP-02 Окно ⓘ «על התפילה» (не утверждено): «על תפילת מנחה», «💡 טיפ», «נוסח זמני…», без «סגירה והמשך בתפילה», ✕ → тот же קטע #6a86f7ff #6a86f7e16f63 @prod-safe', async () => {
    const before = await openInfo('mincha_ashkenaz', 'מנחה');
    await expectVisibleText(TEMP_LINE);
    await expect(byTextContains('אושר על ידי')).not.toBeDisplayed();
    await closeAndCheck('מנחה', before);
  });

  it('GP-02 Окно ⓘ «על התפילה» (утверждено в админке): «על תפילת ערבית», «מקור: … · אושר על ידי …» вместо «נוסח זמני» #6a86f7e16f63 #a5decf4a @prod-safe', async () => {
    const before = await openInfo('arvit_ashkenaz', 'ערבית');
    // На 06.10: «מקור: בדיקת QA · אושר על ידי בודק QA, 6.10.2026» — источник и имя дословно не сверяем (клиент заменит).
    await expect(byTextMatches(APPROVED_LINE)).toBeDisplayed();
    await expect(byText(TEMP_LINE)).not.toBeDisplayed();
    await closeAndCheck('ערבית', before);
  });
});
